 ["%s Select Mode   •   |cff38BDF8◀/▶|r Controls   •   %s Try Texture   •   %s Categories"] = "%s Seleccionar modo   •   |cff38BDF8◀/▶|r Controles   •   %s Probar textura   •   %s Categorías",
 ["%s Switch Category   •   %s Navigate   •   %s Select   •   %s Close"] = "%s Cambiar categoría   •   %s Navegar   •   %s Seleccionar   •   %s Cerrar",
 ["%s Toggle   •   |cff38BDF8▶|r Next Control   •   %s Try Texture   •   %s Categories"] = "%s Alternar   •   |cff38BDF8▶|r Siguiente control   •   %s Probar textura   •   %s Categorías",
 ["%s has no impacts — it is the bed alone, for the length of the craft."] = "%s no tiene impactos: es solo la base de fabricación durante toda la duración de la creación.",
 ["%s is felt as %s struck about %.1f times a second, over the bed."] = "%s se siente como %s asestado alrededor de %.1f veces por segundo, sobre la base continua.",
 ["%s/%s Try Texture   •   |cff38BDF8◀|r Controls   •   %s Categories"] = "%s/%s Probar textura   •   |cff38BDF8◀|r Controles   •   %s Categorías",
 ["'s high-motor intensity. 1.0 is the authored default; the top of this slider is where it stops making any further difference."] = "'s intensidad del motor rápido. 1.0 es el valor predeterminado original; el extremo superior de este deslizador es donde deja de marcar diferencia alguna.",
 ["'s low-motor intensity. 1.0 is the authored default; the top of this slider is where it stops making any further difference."] = "'s intensidad del motor lento. 1.0 es el valor predeterminado original; el extremo superior de este deslizador es donde deja de marcar diferencia alguna.",
 ["(Toggles all continuous sensations)"] = "(Activa o desactiva todas las sensaciones continuas)",
