 [", so there is nothing to test."] = ", por lo que no hay nada que probar.",
 ["0 = one soft pulse. 1 = a sharp lub, then a clearly separate softer dub. Derives the knock timing and intensity split automatically — see lowHealthTexture if you want those set by hand instead."] = "0 = un pulso suave. 1 = un lub seco, seguido de un dub más suave claramente separado. Calcula el intervalo del latido y la división de intensidad automáticamente; consulta lowHealthTexture si deseas configurarlos manualmente.",
 ["1 = every scripted event, 3 = only the most severe. Higher means rarer, more significant warnings."] = "1 = cada evento programado, 3 = solo los más graves. Un valor más alto significa advertencias más raras y significativas.",
 ["1. Controller"] = "1. Control",
 ["1. Planned Class & Combat Role"] = "1. Clase prevista y función de combate",
 ["100% stripped of footsteps, weather, swimming, flight, loot, quest, and UI noise"] = "100% sin sonido de pisadas, clima, natación, vuelo, botín, misiones ni interfaz",
 ["2. Combat"] = "2. Combate",
 ["3. World"] = "3. Mundo",
