 ["Drowning panic peak"] = "Pico de pánico por ahogamiento",
 ["Druid"] = "Druida",
 ["Dual asymmetrical ERM motors, balanced 75ms spin-up"] = "Motores ERM asimétricos dobles, aceleración balanceada de 75 ms",
 ["Dual-motor rumble & vibration schemas"] = "Esquemas de vibración y rumble de doble motor",
 ["DualSense (PS5)"] = "DualSense (PS5)",
 ["DualShock 4 (PS4)"] = "DualShock 4 (PS4)",
 ["Duel request"] = "Petición de duelo",
 ["Dungeon queue popped"] = "Cola de calabozo lista",
 ["Dungeon: Caster"] = "Calabozo: Lanzador",
 ["Dungeon: Caster DPS"] = "Calabozo: DPS lanzador",
 ["Dungeon: Healer"] = "Calabozo: Sanador",
 ["Dungeon: Hunter"] = "Calabozo: Cazador",
